package com.focusflow.api.controller; import com.focusflow.api.dto.ApiDtos.*; import com.focusflow.api.service.TaskService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/tasks") public class TaskController {final TaskService service;public TaskController(TaskService s){service=s;} String uid(Authentication a){return (String)a.getPrincipal();}@GetMapping List<TaskResponse> all(Authentication a){return service.all(uid(a));}@PostMapping @ResponseStatus(HttpStatus.CREATED) TaskResponse create(@Valid @RequestBody TaskRequest r,Authentication a){return service.create(r,uid(a));}@GetMapping("/{id}") TaskResponse one(@PathVariable String id,Authentication a){return service.one(id,uid(a));}@PutMapping("/{id}") TaskResponse update(@PathVariable String id,@Valid @RequestBody TaskRequest r,Authentication a){return service.update(id,r,uid(a));}@PatchMapping("/{id}/complete") TaskResponse complete(@PathVariable String id,Authentication a){return service.complete(id,uid(a));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable String id,Authentication a){service.delete(id,uid(a));}@GetMapping("/today") List<TaskResponse> today(Authentication a){return service.today(uid(a));}@GetMapping("/upcoming") List<TaskResponse> upcoming(Authentication a){return service.upcoming(uid(a));}@GetMapping("/overdue") List<TaskResponse> overdue(Authentication a){return service.overdue(uid(a));} }
